/**
 * @name Code Injection via eval/exec
 * @description Using eval or exec with untrusted input.
 * @kind path-problem
 * @problem.severity error
 * @id py/code-injection
 * @tags security
 *       external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module CodeInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource or
    // Also consider function parameters as potential sources since libraries like Pillow
    // often take input from library users (developers) who might pass untrusted data.
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    sink = any(CodeExecution ce).getCode()
  }
}

module CodeInjectionFlow = TaintTracking::Global<CodeInjectionConfig>;
import CodeInjectionFlow::PathGraph

from CodeInjectionFlow::PathNode source, CodeInjectionFlow::PathNode sink
where CodeInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential code injection from $@.", source.getNode(), "user input"

/**
 * @name Tainted Subprocess in EPS Plugin
 * @description Check if arguments to subprocess in EpsImagePlugin are tainted by function parameters (likely filenames).
 * @kind path-problem
 * @problem.severity error
 * @id py/eps-subprocess-taint
 * @tags security
 *       external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module EpsTaintConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("subprocess").getMember(["call", "Popen", "check_call", "run"]).getACall() and
      sink = call.getArg(0) and
      call.getLocation().getFile().getShortName() = "EpsImagePlugin.py"
    )
  }
}

module EpsTaintFlow = TaintTracking::Global<EpsTaintConfig>;
import EpsTaintFlow::PathGraph

from EpsTaintFlow::PathNode source, EpsTaintFlow::PathNode sink
where EpsTaintFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Tainted subprocess argument from $@.", source.getNode(), "parameter"

/**
 * @name ImageMath Eval Taint
 * @description Check flow from function parameters to eval() in ImageMath.py.
 * @kind path-problem
 * @problem.severity error
 * @id py/imagemath-eval-taint
 * @tags security
 *       external/cwe/cwe-095
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module ImageMathEvalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("eval").getACall() and
      sink = call.getArg(0) and
      call.getLocation().getFile().getShortName() = "ImageMath.py"
    )
  }
}

module ImageMathEvalFlow = TaintTracking::Global<ImageMathEvalConfig>;
import ImageMathEvalFlow::PathGraph

from ImageMathEvalFlow::PathNode source, ImageMathEvalFlow::PathNode sink
where ImageMathEvalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Tainted eval argument from $@.", source.getNode(), "parameter"
